            feature_idx = i % inputs.shape[-1]
            qubit_idx = i + scale * 3
            if qubit_idx < n_qubits:
                # Encode with different rotation types at different scales
                if scale == 0:
                    qml.RX(inputs[..., feature_idx], wires=qubit_idx)
                elif scale == 1:
                    qml.RY(inputs[..., feature_idx], wires=qubit_idx)
                else:
                    qml.RZ(inputs[..., feature_idx], wires=qubit_idx)

    # Multi-scale processing with 2 layers
    for l in range(2):
        # Local rotations
        for i in range(n_qubits):
            qml.RY(weights[l, i, 0], wires=i)
            qml.RZ(weights[l, i, 1], wires=i)

        # Multi-scale entanglement pattern
        # Scale 1: Nearest neighbors
        for i in range(0, n_qubits-1, 3):
            qml.CNOT(wires=[i, i+1])
            if i+2 < n_qubits:
                qml.CNOT(wires=[i+1, i+2])

        # Scale 2: Medium-range connections
        for i in range(0, n_qubits-3, 3):
            qml.CNOT(wires=[i, i+3])

        # Scale 3: Long-range connection
        if n_qubits >= 6:
            qml.CNOT(wires=[0, n_qubits-1])

    # Multi-scale measurements - different observables for different qubit groups
    measurements = []

    # First scale - Z measurements
    for i in range(0, 3):
        measurements.append(qml.expval(qml.PauliZ(i)))

    # Second scale - X measurements
    for i in range(3, 6):
        measurements.append(qml.expval(qml.PauliX(i)))

    # Third scale - Y measurements
    for i in range(6, 9):
        measurements.append(qml.expval(qml.PauliY(i)))

    return measurements

