@qml.qnode(dev, interface="torch")
def circuit(inputs, weights):
    # Initial state preparation with Hadamards
    for i in range(n_qubits):
        qml.Hadamard(wires=i)

    # Adaptive angle encoding - different rotations for different parts of input
    for i in range(n_qubits):
        feature_idx = i % inputs.shape[-1]
        # Apply different rotation gates based on position
        if i < n_qubits // 3:
            qml.RX(inputs[..., feature_idx], wires=i)
        elif i < 2 * (n_qubits // 3):
            qml.RY(inputs[..., feature_idx], wires=i)
        else:
            qml.RZ(inputs[..., feature_idx], wires=i)

    # Three variational layers with different entanglement patterns
    for l in range(3):
        # Parameterized rotations
        for i in range(n_qubits):
            qml.RX(weights[l, i, 0], wires=i)
            qml.RY(weights[l, i, 1], wires=i)
            qml.RZ(weights[l, i, 2], wires=i)

        # Layer-specific entanglement pattern
        if l == 0:
            # First layer: nearest-neighbor
            for i in range(n_qubits-1):
                qml.CNOT(wires=[i, i+1])
        elif l == 1:
            # Second layer: skip connections
            for i in range(0, n_qubits-2, 2):
                qml.CNOT(wires=[i, i+2])
            # Additional entanglement to connect separate sections
            qml.CNOT(wires=[1, n_qubits-2])
        else:
            # Third layer: long-range connections
            qml.CNOT(wires=[0, n_qubits-1])
            qml.CNOT(wires=[n_qubits//2-1, n_qubits//2])
            # Add some CPhase gates for more expressivity
            for i in range(0, n_qubits-1, 2):
                qml.CPhase(weights[l, i, 3], wires=[i, i+1])

    # Final rotation layer to adjust measurement basis
